import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const scanReceipt = async (base64Image: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            {
              inlineData: {
                data: base64Image,
                mimeType: "image/jpeg"
              }
            },
            {
              text: "Analyze this receipt or note. Extract the following information in JSON format: activity (short description), date (format YYYY-MM-DD), amount (number only), and type (either 'IN' for income or 'OUT' for expense). If it's a purchase/bill, it's 'OUT'. If it's a donation/infaq record, it's 'IN'."
            }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            activity: { type: Type.STRING },
            date: { type: Type.STRING },
            amount: { type: Type.NUMBER },
            type: { type: Type.STRING, enum: ["IN", "OUT"] }
          },
          required: ["activity", "date", "amount", "type"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (error) {
    console.error("AI Scan Error:", error);
    throw error;
  }
};

