export default Dashboard;

import React, { useState, useRef } from 'react';
import { Transaction, TransactionType } from '../types';
import { scanReceipt } from '../services/geminiService';

interface TransactionFormProps {
  onAdd: (transaction: Omit<Transaction, 'id'>) => void;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd }) => {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    activity: '',
    amount: '',
    type: 'IN' as TransactionType,
    category: 'Umum'
  });
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.activity || !formData.amount) return;

    onAdd({
      date: formData.date,
      activity: formData.activity,
      amount: parseFloat(formData.amount),
      type: formData.type,
      category: formData.category
    });

    setFormData({
      date: new Date().toISOString().split('T')[0],
      activity: '',
      amount: '',
      type: 'IN',
      category: 'Umum'
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = event.target?.result?.toString().split(',')[1];
        if (base64) {
          const result = await scanReceipt(base64);
          if (result) {
            setFormData({
              date: result.date || new Date().toISOString().split('T')[0],
              activity: result.activity || '',
              amount: result.amount?.toString() || '',
              type: result.type || 'OUT',
              category: 'Hasil Scan AI'
            });
          }
        }
      };
      reader.readAsDataURL(file);
    } catch (err) {
      alert("Gagal memproses foto. Pastikan koneksi internet stabil.");
    } finally {
      setLoading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h4 className="text-slate-800 font-semibold flex items-center gap-2">
          <span className="p-2 bg-emerald-100 rounded-lg text-emerald-600">✍️</span>
          Tambah Data Baru
        </h4>
        <div className="relative group">
          <input 
            type="file" 
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/*"
            className="hidden" 
          />
          <button 
            type="button"
            disabled={loading}
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl transition-all shadow-md active:scale-95 disabled:opacity-50"
          >
            {loading ? '⏳ Memproses...' : '📸 Scan Kuitansi AI'}
          </button>
          <div className="absolute top-full left-0 mt-2 p-2 bg-slate-800 text-white text-[10px] rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50">
            Unggah foto bukti kas untuk input otomatis
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        <div className="space-y-1">
          <label className="text-xs font-medium text-slate-500">Tanggal</label>
          <input 
            type="date" 
            value={formData.date}
            onChange={(e) => setFormData({...formData, date: e.target.value})}
            className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-medium text-slate-500">Keterangan Kegiatan</label>
          <input 
            type="text" 
            placeholder="Contoh: Infaq Jumat"
            value={formData.activity}
            onChange={(e) => setFormData({...formData, activity: e.target.value})}
            className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-medium text-slate-500">Jumlah (Rp)</label>
          <input 
            type="number" 
            placeholder="0"
            value={formData.amount}
            onChange={(e) => setFormData({...formData, amount: e.target.value})}
            className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-medium text-slate-500">Tipe</label>
          <select 
            value={formData.type}
            onChange={(e) => setFormData({...formData, type: e.target.value as TransactionType})}
            className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          >
            <option value="IN">Masuk (+)</option>
            <option value="OUT">Keluar (-)</option>
          </select>
        </div>
        <div className="flex items-end">
          <button 
            type="submit"
            className="w-full py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors shadow-sm font-medium"
          >
            Simpan Data
          </button>
        </div>
      </form>
    </div>
  );
};

export default TransactionForm;

import React from 'react';
