              transactions.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map((t) => (
                <tr key={t.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600 font-medium">{t.date}</td>
                  <td className="px-6 py-4 text-sm text-slate-800">
                    <div className="flex items-center gap-2">
                       <span className={`w-2 h-2 rounded-full ${t.type === 'IN' ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
                       {t.activity}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2 py-1 bg-slate-100 text-slate-600 text-[10px] rounded-full uppercase font-bold">
                      {t.category}
                    </span>
                  </td>
                  <td className={`px-6 py-4 text-sm font-bold text-right ${t.type === 'IN' ? 'text-emerald-600' : 'text-red-600'}`}>
                    {t.type === 'IN' ? '+' : '-'} {formatIDR(t.amount)}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <button 
                      onClick={() => onDelete(t.id)}
                      className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                    >
                      🗑️
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default TransactionList;

