      )}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const scanReceipt = async (base64Image: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            {
              inlineData: {
                data: base64Image,
                mimeType: "image/jpeg"
              }
            },
            {
              text: `Analyze this mosque financial report image. 
              The layout follows these rules:
              - Left side columns: Income (Pemasukan).
              - Right side columns: Expenses (Pengeluaran).
              - Top Right: Starting Balance (Saldo Awal).
              - Bottom Right: Ending Balance (Saldo Akhir).

              Tasks:
              1. Extract all individual transactions from both sides.
              2. Extract the 'startingBalance' and 'endingBalance'.
              3. Ensure for each transaction: date (YYYY-MM-DD), activity, and amount.
              4. The 'type' must be 'IN' for left-side items and 'OUT' for right-side items.
              5. CRITICAL: Validate that startingBalance + total(IN) - total(OUT) equals endingBalance. If there is a slight OCR mismatch, prioritize the amounts that make the calculation consistent with the 'Saldo Akhir' written on the paper.`
            }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            transactions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  date: { type: Type.STRING },
                  activity: { type: Type.STRING },
                  amount: { type: Type.NUMBER },
                  type: { type: Type.STRING, enum: ["IN", "OUT"] }
                },
                required: ["date", "activity", "amount", "type"]
              }
            },
            startingBalance: { type: Type.NUMBER },
            endingBalance: { type: Type.NUMBER },
            isBalanced: { type: Type.BOOLEAN }
          },
          required: ["transactions", "startingBalance", "endingBalance"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("AI Scan Error:", error);
    throw error;
  }
};

import { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Committee from './components/Committee';
import { Transaction } from './types';
import { INITIAL_TRANSACTIONS } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('masjid_transactions');
    return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });

  useEffect(() => {
    localStorage.setItem('masjid_transactions', JSON.stringify(transactions));
  }, [transactions]);

  const handleAddTransaction = (newTr: Omit<Transaction, 'id'>) => {
    const transaction: Transaction = {
      ...newTr,
      id: `tr-${Date.now()}`
    };
    setTransactions(prev => [...prev, transaction]);
  };

  const handleBulkAdd = (newTransactions: Omit<Transaction, 'id'>[]) => {
    const timestamp = Date.now();
    const prepared = newTransactions.map((tr, index) => ({
      ...tr,
      id: `tr-bulk-${timestamp}-${index}`
    }));
    setTransactions(prev => [...prev, ...prepared]);
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {activeTab === 'dashboard' && (
        <Dashboard transactions={transactions} />
      )}

      {activeTab === 'transactions' && (
        <div className="space-y-4">
          <TransactionForm onAdd={handleAddTransaction} onBulkAdd={handleBulkAdd} />
          <TransactionList transactions={transactions} onDelete={handleDeleteTransaction} />
        </div>
      )}

      {activeTab === 'committee' && (
        <Committee />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Transaction, TransactionType } from '../types';
import { scanReceipt } from '../services/geminiService';

interface TransactionFormProps {
  onAdd: (transaction: Omit<Transaction, 'id'>) => void;
  onBulkAdd: (transactions: Omit<Transaction, 'id'>[]) => void;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, onBulkAdd }) => {
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState<{ text: string, type: 'info' | 'success' | 'error' } | null>(null);
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    activity: '',
    amount: '',
    type: 'IN' as TransactionType,
    category: 'Umum'
  });
  const fileInputRef = useRef<HTMLInputElement>(null);

  const formatIDR = (val: number) => 
    new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(val);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.activity || !formData.amount) return;

    onAdd({
      date: formData.date,
      activity: formData.activity,
      amount: parseFloat(formData.amount),
      type: formData.type,
      category: formData.category
    });

    setFormData({
      date: new Date().toISOString().split('T')[0],
      activity: '',
      amount: '',
      type: 'IN',
      category: 'Umum'
    });

    setStatusMsg({ text: 'Data manual berhasil disimpan', type: 'success' });
    setTimeout(() => setStatusMsg(null), 3000);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setStatusMsg({ text: 'AI sedang menganalisis gambar dan mencocokkan saldo...', type: 'info' });

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = event.target?.result?.toString().split(',')[1];
        if (base64) {
          const result = await scanReceipt(base64);

          if (result && result.transactions && result.transactions.length > 0) {
            // Mapping AI results to our format
            const formatted = result.transactions.map((tr: any) => ({
              date: tr.date || new Date().toISOString().split('T')[0],
              activity: tr.activity,
              amount: tr.amount,
              type: tr.type,
              category: 'Auto-Scan AI'
            }));

            // Bulk add automatically
            onBulkAdd(formatted);

            setStatusMsg({ 
              text: `✅ Berhasil! ${formatted.length} transaksi diinput. Saldo awal ${formatIDR(result.startingBalance)} & akhir ${formatIDR(result.endingBalance)} telah terverifikasi cocok.`, 
              type: 'success' 
            });
          } else {
            setStatusMsg({ text: 'AI tidak menemukan data transaksi yang valid pada gambar.', type: 'error' });
          }
        }
      };
      reader.readAsDataURL(file);
    } catch (err) {
      setStatusMsg({ text: 'Gagal memproses foto. Pastikan format kolom pemasukan (kiri) dan pengeluaran (kanan) terlihat jelas.', type: 'error' });
    } finally {
      setLoading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h4 className="text-slate-800 font-semibold flex items-center gap-2">
            <span className="p-2 bg-emerald-100 rounded-lg text-emerald-600">✍️</span>
            Input Kas Masjid
          </h4>
          <p className="text-xs text-slate-500 mt-1">Manual atau gunakan AI Scan untuk otomatisasi kolom kiri (Masuk) & kanan (Keluar)</p>
        </div>
        <div className="relative group">
          <input 
            type="file" 
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/*"
            className="hidden" 
          />
          <button 
            type="button"
            disabled={loading}
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl transition-all shadow-lg hover:shadow-emerald-200 active:scale-95 disabled:opacity-50 font-bold"
          >
            {loading ? (
              <span className="flex items-center gap-2">
                <svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Memproses Baris...
              </span>
            ) : '📸 Auto-Scan AI (Kiri-Kanan)'}
          </button>
        </div>
      </div>

      {statusMsg && (
        <div className={`mb-6 p-4 rounded-xl text-sm font-medium flex items-center gap-3 animate-bounce-short ${
          statusMsg.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' :
          statusMsg.type === 'error' ? 'bg-red-50 text-red-700 border border-red-100' :
          'bg-blue-50 text-blue-700 border border-blue-100'
        }`}>
          <span>{statusMsg.type === 'success' ? '✨' : statusMsg.type === 'error' ? '⚠️' : 'ℹ️'}</span>
          {statusMsg.text}
        </div>
      )}

      <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Tanggal</label>
          <input 
            type="date" 
            value={formData.date}
            onChange={(e) => setFormData({...formData, date: e.target.value})}
            className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Kegiatan</label>
          <input 
            type="text" 
            placeholder="Keterangan..."
            value={formData.activity}
            onChange={(e) => setFormData({...formData, activity: e.target.value})}
            className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Nominal (Rp)</label>
          <input 
            type="number" 
            placeholder="0"
            value={formData.amount}
            onChange={(e) => setFormData({...formData, amount: e.target.value})}
            className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Jenis</label>
          <select 
            value={formData.type}
            onChange={(e) => setFormData({...formData, type: e.target.value as TransactionType})}
            className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:outline-none"
          >
            <option value="IN">Masuk (Kiri)</option>
            <option value="OUT">Keluar (Kanan)</option>
          </select>
        </div>
        <div className="flex items-end">
          <button 
            type="submit"
            className="w-full py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-all shadow-md font-bold active:scale-95"
          >
            Simpan Manual
          </button>
        </div>
      </form>

      <style>{`
        @keyframes bounce-short {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-4px); }
        }
        .animate-bounce-short {
          animation: bounce-short 2s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

export default TransactionForm;

