import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Committee from './components/Committee';
import LoginForm from './components/LoginForm';
import { Transaction } from './types';
import { INITIAL_TRANSACTIONS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState<boolean>(() => {
    return sessionStorage.getItem('is_admin_logged_in') === 'true';
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('masjid_transactions');
    return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });

  useEffect(() => {
    localStorage.setItem('masjid_transactions', JSON.stringify(transactions));
  }, [transactions]);

  const handleLogin = (user: string, pass: string) => {
    if (user === 'admin' && pass === 'adminjmnh') {
      setIsLoggedIn(true);
      sessionStorage.setItem('is_admin_logged_in', 'true');
      return true;
    }
    return false;
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    sessionStorage.removeItem('is_admin_logged_in');
  };

  const handleAddTransaction = (newTr: Omit<Transaction, 'id'>) => {
    const transaction: Transaction = {
      ...newTr,
      id: `tr-${Date.now()}`
    };
    setTransactions(prev => [...prev, transaction]);
  };

  const handleBulkAdd = (newTransactions: Omit<Transaction, 'id'>[]) => {
    const timestamp = Date.now();
    const prepared = newTransactions.map((tr, index) => ({
      ...tr,
      id: `tr-bulk-${timestamp}-${index}`
    }));
    setTransactions(prev => [...prev, ...prepared]);
  };

  const handleUpdateTransaction = (updatedTr: Transaction) => {
    setTransactions(prev => prev.map(t => t.id === updatedTr.id ? updatedTr : t));
  };

  const handleDeleteTransaction = (id: string) => {
    const confirmDelete = window.confirm('Apakah Anda yakin ingin menghapus data transaksi ini?');
    if (confirmDelete) {
      setTransactions(prevTransactions => {
        const filtered = prevTransactions.filter(t => t.id !== id);
        return [...filtered];
      });
    }
  };

  const handleExportCSV = () => {
    const headers = ['ID', 'Tanggal', 'Kegiatan', 'Tipe', 'Nominal', 'Kategori'];
    const rows = transactions.map(t => [
      t.id, 
      t.date, 
      t.activity.replace(/,/g, ''), 
      t.type, 
      t.amount, 
      t.category
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n" 
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `laporan_kas_nurul_huda_${new Date().toLocaleDateString()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (!isLoggedIn) {
    return <LoginForm onLogin={handleLogin} />;
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="flex justify-end mb-4">
        <button 
          onClick={handleLogout}
          className="text-xs bg-red-50 text-red-600 px-3 py-1 rounded-lg hover:bg-red-100 transition-colors border border-red-100"
        >
          Logout Admin
        </button>
      </div>

      {activeTab === 'dashboard' && (
        <Dashboard transactions={transactions} />
      )}

      {activeTab === 'transactions' && (
        <div className="space-y-4">
          <div className="flex justify-end">
             <button 
               onClick={handleExportCSV}
               className="text-xs bg-emerald-50 text-emerald-700 px-3 py-2 rounded-lg hover:bg-emerald-100 transition-all border border-emerald-200 font-bold flex items-center gap-2"
             >
               📥 Download CSV (Buka di Excel)
             </button>
          </div>
          <TransactionForm onAdd={handleAddTransaction} onBulkAdd={handleBulkAdd} />
          <TransactionList 
            transactions={transactions} 
            onDelete={handleDeleteTransaction} 
            onUpdate={handleUpdateTransaction}
          />
        </div>
      )}

      {activeTab === 'committee' && (
        <Committee />
      )}
    </Layout>
  );
};

export default App;
